import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec4 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry with atlas aspect ratio (512x320 = 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Material with texture loading
  const material = new MeshBasicNodeMaterial();

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.copy(new THREE.Vector3(0, -0.3, 0));

  // Load and apply sprite texture
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((texture) => {
    texture.flipY = false;
    texture.colorSpace = 'srgb';

    // UV mapping for atlas region (0, 0, 512, 320 of full atlas)
    // Assuming full atlas dimensions; adjust offset if needed
    const uvNode = uv();

    // Apply texture via TSL node
    material.colorNode = texture.uv(uvNode);
    material.needsUpdate = true;
  });

  // Setup cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
